=== hazy-note schema ===
import {
  pgTable,
  unique,
  uuid,
  varchar,
  text,
  timestamp,
  index,
  foreignKey,
  boolean,
  integer,
  jsonb,
  pgEnum,
  customType,
} from "drizzle-orm/pg-core";
import { sql } from "drizzle-orm";

// Introspected from the existing Neon database (drizzle-kit pull, 2026-08-28).
// The database is the source of truth — these definitions mirror the live
// tables. Two things drizzle-kit could not round-trip and were fixed by hand:
//   - saved_urls.search_vector: Postgres `tsvector` has no built-in Drizzle
//     type, so it is declared through customType below.
//   - saved_urls.tags default: the real default is an empty array
//     (`ARRAY[]::text[]`); drizzle-kit misparsed it as `{"RAY"}`.

const tsvector = customType<{ data: string; notNull: false; default: false }>({
  dataType() {
    return "tsvector";
  },
});

export const answer_language_mode = pgEnum("answer_language_mode", [
  "interface",
  "source",
]);
export const ask_role = pgEnum("ask_role", ["user", "assistant"]);
export const fetch_status = pgEnum("fetch_status", [
  "pending",
  "success",
  "error",
]);
export const locale = pgEnum("locale", ["en", "ja"]);
export const read_later_status = pgEnum("read_later_status", [
  "inbox",
  "snoozed",
  "read",
  "archived",
]);

// Added for the hazy-note app domain (Item/Note/CompareBoard/GraphData in
// lib/types.ts), on top of the pre-existing read-later schema above.
export const source_kind = pgEnum("source_kind", [
  "article",
  "pdf",
  "video",
  "thread",
  "note",
]);
export const note_status = pgEnum("note_status", ["draft", "done"]);

export const users = pgTable(
  "users",
  {
    id: uuid().defaultRandom().primaryKey().notNull(),
    clerk_id: varchar({ length: 191 }).notNull(),
    email: varchar({ length: 320 }),
    display_name: varchar({ length: 255 }),
    avatar_url: text(),
    created_at: timestamp({ withTimezone: true, mode: "string" })
      .defaultNow()
      .notNull(),
    updated_at: timestamp({ withTimezone: true, mode: "string" })
      .defaultNow()
      .notNull(),
  },
  (table) => [unique("users_clerk_id_unique").on(table.clerk_id)],
);

export const collections = pgTable(
  "collections",
  {
    id: uuid().defaultRandom().primaryKey().notNull(),
    user_id: uuid().notNull(),
    name: varchar({ length: 255 }).notNull(),
    description: text(),
    color: varchar({ length: 32 }),
    created_at: timestamp({ withTimezone: true, mode: "string" })
      .defaultNow()
      .notNull(),
    updated_at: timestamp({ withTimezone: true, mode: "string" })
      .defaultNow()
      .notNull(),
    summary: text(),
    summary_updated_at: timestamp({ withTimezone: true, mode: "string" }),
    // hazy-note app domain: Project.tone.
    tone: varchar({ length: 16 }).default("neutral").notNull(),
  },
  (table) => [
    index("collections_user_id_idx").using("btree", table.user_id),
    foreignKey({
      columns: [table.user_id],
      foreignColumns: [users.id],
      name: "collections_user_id_users_id_fk",
    }).onDelete("cascade"),
  ],
);

export const user_preferences = pgTable(
  "user_preferences",
  {
    user_id: uuid().primaryKey().notNull(),
    interface_locale: locale().default("en").notNull(),
    answer_language_mode: answer_language_mode().default("interface").notNull(),
    notify_read_later_digest: boolean().default(true).notNull(),
    notify_weekly_stats: boolean().default(false).notNull(),
    updated_at: timestamp({ withTimezone: true, mode: "string" })
      .defaultNow()
      .notNull(),
  },
  (table) => [
    foreignKey({
      columns: [table.user_id],
      foreignColumns: [users.id],
      name: "user_preferences_user_id_users_id_fk",
    }).onDelete("cascade"),
  ],
);

export const collection_items = pgTable(
  "collection_items",
  {
    id: uuid().defaultRandom().primaryKey().notNull(),
    collection_id: uuid().notNull(),
    saved_url_id: uuid().notNull(),
    created_at: timestamp({ withTimezone: true, mode: "string" })
      .defaultNow()
      .notNull(),
  },
  (table) => [
    foreignKey({
      columns: [table.collection_id],
      foreignColumns: [collections.id],
      name: "collection_items_collection_id_collections_id_fk",
    }).onDelete("cascade"),
    foreignKey({
      columns: [table.saved_url_id],
      foreignColumns: [saved_urls.id],
      name: "collection_items_saved_url_id_saved_urls_id_fk",
    }).onDelete("cascade"),
    unique("collection_items_collection_saved_url_unique").on(
      table.saved_url_id,
      table.collection_id,
    ),
  ],
);

export const ask_threads = pgTable(
  "ask_threads",
  {
    id: uuid().defaultRandom().primaryKey().notNull(),
    user_id: uuid().notNull(),
    title: text().notNull(),
    created_at: timestamp({ withTimezone: true, mode: "string" })
      .defaultNow()
      .notNull(),
    updated_at: timestamp({ withTimezone: true, mode: "string" })
      .defaultNow()
      .notNull(),
  },
  (table) => [
    index("ask_threads_user_id_idx").using("btree", table.user_id),
    foreignKey({
      columns: [table.user_id],
      foreignColumns: [users.id],
      name: "ask_threads_user_id_users_id_fk",
    }).onDelete("cascade"),
  ],
);

export const ask_messages = pgTable(
  "ask_messages",
  {
    id: uuid().defaultRandom().primaryKey().notNull(),
    thread_id: uuid().notNull(),
    role: ask_role().notNull(),
    content: text().notNull(),
    model_id: varchar({ length: 255 }),
    used_fallback: boolean().default(false).notNull(),
    created_at: timestamp({ withTimezone: true, mode: "string" })
      .defaultNow()
      .notNull(),
  },
  (table) => [
    index("ask_messages_thread_id_idx").using("btree", table.thread_id),
    foreignKey({
      columns: [table.thread_id],
      foreignColumns: [ask_threads.id],
      name: "ask_messages_thread_id_ask_threads_id_fk",
    }).onDelete("cascade"),
  ],
);

export const ask_message_citations = pgTable(
  "ask_message_citations",
  {
    id: uuid().defaultRandom().primaryKey().notNull(),
    message_id: uuid().notNull(),
    saved_url_id: uuid().notNull(),
    rank: integer().notNull(),
    snippet: text(),
  },
  (table) => [
    index("ask_citations_message_id_idx").using("btree", table.message_id),
    foreignKey({
      columns: [table.message_id],
      foreignColumns: [ask_messages.id],
      name: "ask_message_citations_message_id_ask_messages_id_fk",
    }).onDelete("cascade"),
    foreignKey({
      columns: [table.saved_url_id],
      foreignColumns: [saved_urls.id],
      name: "ask_message_citations_saved_url_id_saved_urls_id_fk",
    }).onDelete("cascade"),
  ],
);

export const read_later_state = pgTable(
  "read_later_state",
  {
    id: uuid().defaultRandom().primaryKey().notNull(),
    user_id: uuid().notNull(),
    saved_url_id: uuid().notNull(),
    status: read_later_status().default("inbox").notNull(),
    snoozed_until: timestamp({ withTimezone: true, mode: "string" }),
    marked_read_at: timestamp({ withTimezone: true, mode: "string" }),
    created_at: timestamp({ withTimezone: true, mode: "string" })
      .defaultNow()
      .notNull(),
    updated_at: timestamp({ withTimezone: true, mode: "string" })
      .defaultNow()
      .notNull(),
  },
  (table) => [
    index("read_later_user_status_idx").using(
      "btree",
      table.user_id,
      table.status,
    ),
    foreignKey({
      columns: [table.user_id],
      foreignColumns: [users.id],
      name: "read_later_state_user_id_users_id_fk",
    }).onDelete("cascade"),
    foreignKey({
      columns: [table.saved_url_id],
      foreignColumns: [saved_urls.id],
      name: "read_later_state_saved_url_id_saved_urls_id_fk",
    }).onDelete("cascade"),
    unique("read_later_user_saved_url_unique").on(
      table.user_id,
      table.saved_url_id,
    ),
  ],
);

export const saved_urls = pgTable(
  "saved_urls",
  {
    id: uuid().defaultRandom().primaryKey().notNull(),
    user_id: uuid().notNull(),
    url: text().notNull(),
    normalized_url: text().notNull(),
    domain: varchar({ length: 255 }),
    title: text(),
    description: text(),
    favicon_url: text(),
    og_image_url: text(),
    summary: text(),
    extracted_text: text(),
    content_language: varchar({ length: 8 }),
    estimated_read_minutes: integer(),
    fetch_status: fetch_status().default("pending").notNull(),
    fetch_error: text(),
    search_vector: tsvector("search_vector"),
    created_at: timestamp({ withTimezone: true, mode: "string" })
      .defaultNow()
      .notNull(),
    updated_at: timestamp({ withTimezone: true, mode: "string" })
      .defaultNow()
      .notNull(),
    tags: text()
      .array()
      .default(sql`ARRAY[]::text[]`)
      .notNull(),
    // hazy-note app domain: the rest of Item that has no home in the
    // read-later schema above. All additive/nullable — read_later_state
    // already carries status via fetch_status; these are new hazy fields.
    kind: source_kind().default("article").notNull(),
    points: text()
      .array()
      .default(sql`ARRAY[]::text[]`)
      .notNull(),
    suggested_tags: text()
      .array()
      .default(sql`ARRAY[]::text[]`)
      .notNull(),
    duration_label: text(),
    quote_candidates: integer().default(0).notNull(),
    related_note_id: uuid(),
    // Item.summary is a short bullet list; distinct from the pre-existing
    // free-text `summary` column above (used by the read-later app for a
    // prose blurb).
    summary_lines: text()
      .array()
      .default(sql`ARRAY[]::text[]`)
      .notNull(),
  },
  (table) => [
    index("saved_urls_search_vector_idx").using("gin", table.search_vector),
    index("saved_urls_tags_idx").using("gin", table.tags),
    index("saved_urls_user_id_idx").using("btree", table.user_id),
    foreignKey({
      columns: [table.user_id],
      foreignColumns: [users.id],
      name: "saved_urls_user_id_users_id_fk",
    }).onDelete("cascade"),
    unique("saved_urls_user_normalized_unique").on(
      table.user_id,
      table.normalized_url,
    ),
    foreignKey({
      columns: [table.related_note_id],
      foreignColumns: [notes.id],
      name: "saved_urls_related_note_id_notes_id_fk",
    }).onDelete("set null"),
  ],
);

// ─────────────────────────────────────────────────────────────
// hazy-note app domain — new tables (Note / CompareBoard / GraphData in
// lib/types.ts have no equivalent in the pre-existing read-later schema).
// The richly-shaped, still-canned-AI bits (note blocks, compare axes, graph
// nodes/edges) are kept as jsonb rather than fully normalized: they mirror
// the TS types in lib/types.ts directly and nothing else needs to query into
// their internals yet.
// ─────────────────────────────────────────────────────────────

export const notes = pgTable(
  "notes",
  {
    id: uuid().defaultRandom().primaryKey().notNull(),
    user_id: uuid().notNull(),
