import { db, schema } from "./index";

/**
 * First-run setup for a brand-new user. The app used to seed a full demo
 * workspace here; it now starts empty and every surface is built from the
 * user's own captures. We still create the three default collections so the
 * sidebar and "振り分け" have somewhere to put things — the accent one is the
 * default destination the digest and auto-sort target.
 */
export async function seedForUser(userId: string) {
  const already = await db.query.collections.findFirst({
    where: (c, { eq }) => eq(c.user_id, userId),
  });
  if (already) return;

  await db.insert(schema.collections).values([
    { user_id: userId, name: "いま気になっていること", tone: "accent" },
    { user_id: userId, name: "あとで読む", tone: "neutral" },
  ]);
}

import { relations } from "drizzle-orm/relations";
import {
  users,
  collections,
  user_preferences,
  collection_items,
  saved_urls,
  ask_threads,
  ask_messages,
  ask_message_citations,
  read_later_state,
  notes,
  compare_boards,
  graph_snapshots,
} from "./schema";

export const usersRelations = relations(users, ({ many, one }) => ({
  collections: many(collections),
  user_preferences: many(user_preferences),
  ask_threads: many(ask_threads),
  read_later_states: many(read_later_state),
  saved_urls: many(saved_urls),
  notes: many(notes),
  compare_boards: many(compare_boards),
  graph_snapshot: one(graph_snapshots, {
    fields: [users.id],
    references: [graph_snapshots.user_id],
  }),
}));

export const collectionsRelations = relations(collections, ({ one, many }) => ({
  user: one(users, {
    fields: [collections.user_id],
    references: [users.id],
  }),
  collection_items: many(collection_items),
  notes: many(notes),
  compare_boards: many(compare_boards),
}));

export const notesRelations = relations(notes, ({ one }) => ({
  user: one(users, {
    fields: [notes.user_id],
    references: [users.id],
  }),
  collection: one(collections, {
    fields: [notes.collection_id],
    references: [collections.id],
  }),
