/**
 * GET /api/items/importable — the "Hazyから追加" picker. Saved URLs the user
 * already has in hazy (same shared `saved_urls` table) that aren't filed into
 * a hazy-note project yet. Selecting one runs it through the capture pipeline
 * (`/capture?id=…` → finishReading → 要約とタグ → 置き場所). Pasted memos
 * (`kind: "note"`) are excluded — this is for real URLs.
 */
export async function listImportable(userId: string): Promise<Item[]> {
  const rows = await db.query.saved_urls.findMany({
    where: (t, { and, eq, ne }) =>
      and(eq(t.user_id, userId), ne(t.kind, "note")),
    with: { collection_items: true },
    orderBy: (t, { desc }) => [desc(t.created_at)],
  });
  return rows.filter((r) => r.collection_items.length === 0).map(toItem);
}

