608	  return getNote(userId, noteId);
609	}
610	
611	// ── Compare ────────────────────────────────────────────────
612	function toCompare(row: typeof schema.compare_boards.$inferSelect): CompareBoard {
613	  return {
614	    id: row.id,
615	    projectId: row.collection_id ?? "",
616	    sources: row.sources,
617	    axes: row.axes as CompareBoard["axes"],
618	    summary: row.summary,
619	    candidateAxes: row.candidate_axes,
620	  };
621	}
622	
623	export async function getCompare(userId: string): Promise<CompareBoard | undefined> {
624	  const row = await db.query.compare_boards.findFirst({
625	    where: (t, { eq }) => eq(t.user_id, userId),
626	    orderBy: (t, { desc }) => [desc(t.updated_at)],
627	  });
628	  return row ? toCompare(row) : undefined;
629	}
630	
631	/**
632	 * "差分をまとめる" — (re)build the compare board from the ready sources in a
633	 * project (or, with no project, every ready source). Needs ≥2 sources.
634	 */
635	export async function buildCompareBoard(
636	  userId: string,
637	  projectId?: string,
638	): Promise<CompareBoard> {
639	  const rows = await db.query.saved_urls.findMany({
640	    where: (t, { and, eq }) =>
641	      and(eq(t.user_id, userId), eq(t.fetch_status, "success")),
642	    with: { collection_items: true },
643	    orderBy: (t, { desc }) => [desc(t.created_at)],
644	  });
645	  const items = rows
646	    .map(toItem)
647	    .filter((it) => (projectId ? it.projectId === projectId : true))
648	    .filter((it) => it.summary.length > 0)
649	    .slice(0, 8);
650	
651	  const synth = await synthesiseCompare(
652	    items.map((it) => ({ title: it.title, summary: it.summary })),
653	  );
654	
655	  await db
656	    .delete(schema.compare_boards)
657	    .where(
658	      and(
659	        eq(schema.compare_boards.user_id, userId),
660	        projectId
661	          ? eq(schema.compare_boards.collection_id, projectId)
662	          : isNull(schema.compare_boards.collection_id),
663	      ),
664	    );
665	  const [row] = await db
666	    .insert(schema.compare_boards)
667	    .values({
668	      user_id: userId,
669	      collection_id: projectId ?? null,
670	      sources: items.map((it) => it.title),
671	      axes: synth.axes,
672	      summary: synth.summary,
673	      candidate_axes: synth.candidateAxes,
674	    })
675	    .returning();
676	  return toCompare(row);
677	}
678	
679	// ── Graph ──────────────────────────────────────────────────
680	const GRAPH_W = 840;
681	const GRAPH_H = 600;
682	
683	/** Deterministic ring layout so re-renders don't jump nodes around. */
684	function ringLayout(n: number, i: number, radius: number) {
685	  if (n === 1) return { x: GRAPH_W / 2, y: GRAPH_H / 2 };
686	  const a = (i / n) * Math.PI * 2 - Math.PI / 2;
687	  return {
688	    x: Math.round(GRAPH_W / 2 + Math.cos(a) * radius),
689	    y: Math.round(GRAPH_H / 2 + Math.sin(a) * radius),
690	  };
691	}
692	
693	export async function buildGraph(userId: string): Promise<GraphData> {
694	  const notes = await listNotes(userId);
695	  const sourceRows = await db.query.saved_urls.findMany({
696	    where: (t, { and, eq }) =>
697	      and(eq(t.user_id, userId), eq(t.fetch_status, "success")),
698	    with: { collection_items: true },
699	    orderBy: (t, { desc }) => [desc(t.created_at)],
700	  });
701	  const sources = sourceRows.map(toItem).slice(0, 12);
702	
703	  const noteIds = new Set(notes.map((n) => n.id));
704	  const nodes: GraphData["nodes"] = [
705	    ...notes.map((n, i) => ({
706	      id: n.id,
707	      label: n.title,
708	      kind: "note" as const,
709	      ...ringLayout(Math.max(notes.length, 1), i, notes.length > 3 ? 150 : 90),
710	      r: 40,
711	      focus: i === 0 && notes.length > 0,
712	    })),
713	    ...sources.map((s, i) => ({
714	      id: s.id,
715	      label: s.title,
716	      kind: "source" as const,
717	      ...ringLayout(Math.max(sources.length, 1), i, 250),
718	      r: 26,
719	    })),
720	  ];
721	
722	  const edges: GraphData["edges"] = [];
723	  // note → note links the user (or a prior AI pass) already recorded.
724	  for (const n of notes) {
725	    for (const l of n.links) {
726	      if (noteIds.has(l.noteId) && n.id < l.noteId) {
727	        edges.push({
728	          id: `c-${n.id}-${l.noteId}`,
729	          from: n.id,
730	          to: l.noteId,
731	          kind: "citation",
732	          title: `${n.title} ↔ ${l.title}`,
733	          reason: l.reason,
734	        });
735	      }
736	    }
737	  }
738	  // source → note when the capture was filed against a note.
739	  for (const s of sources) {
740	    if (s.relatedNoteId && noteIds.has(s.relatedNoteId)) {
741	      edges.push({
742	        id: `c-${s.id}-${s.relatedNoteId}`,
743	        from: s.id,
744	        to: s.relatedNoteId,
745	        kind: "citation",
746	        title: `${s.title} → ノート`,
747	      });
748	    }
749	  }
750	  // AI-guessed connections between anything not already linked.
751	  const linked = new Set(edges.flatMap((e) => [e.from, e.to]));
752	  const guesses = await suggestConnections([
753	    ...notes.map((n) => ({
754	      id: n.id,
755	      label: n.title,
756	      text: n.blocks.map((b) => ("text" in b ? b.text : "")).join(" "),
757	    })),
758	    ...sources.map((s) => ({ id: s.id, label: s.title, text: s.summary.join(" ") })),
759	  ]);
760	  for (const g of guesses) {
761	    const key = [g.from, g.to].sort().join("-");
762	    if (edges.some((e) => [e.from, e.to].sort().join("-") === key)) continue;
763	    edges.push({ id: `h-${key}`, from: g.from, to: g.to, kind: "hypothesis", reason: g.reason });
764	    linked.add(g.from);
765	    linked.add(g.to);
766	  }
767	
768	  const isolated = [...notes, ...sources]
769	    .filter((x) => !linked.has(x.id) && !edges.some((e) => e.from === x.id || e.to === x.id))
770	    .map((x) => ("title" in x ? x.title : ""))
771	    .filter(Boolean);
772	
773	  await db
774	    .insert(schema.graph_snapshots)
775	    .values({ user_id: userId, nodes, edges, isolated })
776	    .onConflictDoUpdate({
777	      target: schema.graph_snapshots.user_id,
778	      set: { nodes, edges, isolated, updated_at: new Date().toISOString() },
779	    });
780	  return { nodes, edges, isolated };
781	}
782	
783	export async function getGraph(userId: string): Promise<GraphData> {
784	  const row = await db.query.graph_snapshots.findFirst({
785	    where: (t, { eq }) => eq(t.user_id, userId),
786	  });
787	  if (row) {
788	    return {
789	      nodes: row.nodes as GraphData["nodes"],
790	      edges: row.edges as GraphData["edges"],
791	      isolated: row.isolated as string[],
792	    };
793	  }
794	  return buildGraph(userId);
795	}
796	
797	// ── Export ─────────────────────────────────────────────────
798	function countChars(blocks: { text?: string }[]): number {
799	  return blocks.reduce((n, b) => n + (b.text?.length ?? 0), 0);
800	}
801	
802	export async function buildExport(
803	  userId: string,
804	  noteId: string,
805	  format: ExportFormat = "blog",
806	): Promise<ExportDraft> {
807	  let note = await getNote(userId, noteId);
808	  if (!note) {
809	    const fallback = await db.query.notes.findFirst({
810	      where: (t, { eq }) => eq(t.user_id, userId),
811	      orderBy: (t, { desc }) => [desc(t.updated_at)],
812	    });
813	    note = fallback ? toNote(fallback) : undefined;
814	  }
815	  if (!note) {
816	    return {
817	      format,
818	      meta: "ノートがありません",
819	      title: "書き出すノートがありません",
820	      blocks: [{ type: "p", text: "先にノートを作成してください。" }],
821	      provenance: [],
822	    };
823	  }
824	
825	  const draft = await rewriteForExport({
826	    title: note.title,
827	    blocks: note.blocks,
828	    format,
829	  });
830	  const chars = countChars(draft.blocks);
831	  const minutes = Math.max(1, Math.round(chars / 500));
832	  const meta =
833	    format === "bullets"
834	      ? `${draft.blocks.filter((b) => b.type === "p").length}項目`
835	      : `約${chars.toLocaleString()}字 · 読了${minutes}分`;
836	
837	  return { format, meta, ...draft };
838	}
