import { listImportable, listItems, listNotes, listProjects, getDigest } from "@/lib/db/repo";
import { db } from "@/lib/db/index";

async function main() {
  const u = await db.query.users.findFirst({
    where: (t, { eq }) => eq(t.email, "n.knight.pc0627@gmail.com"),
  });
  if (!u) return console.log("no user");
  console.log("user", u.id);
  console.log("items:", (await listItems(u.id)).length);
  console.log("importable:", (await listImportable(u.id)).map((i) => `${i.title} [${i.summary.length > 0 || i.projectId ? "worked" : "new"}]`));
  console.log("projects:", (await listProjects(u.id)).map((p) => `${p.name}(${p.count})`));
  console.log("notes:", (await listNotes(u.id)).length);
  console.log("digest:", (await getDigest(u.id)).message);
}
main().then(() => process.exit(0)).catch((e) => { console.error(e); process.exit(1); });

