/** Look for an `@token` before the caret. Reads the live DOM value, not the
 * `value` prop (which lags a render behind a keystroke). */
function scan() {
  const el = ref.current;
  if (!el) return;
  const text = el.value;
  const caret = el.selectionStart ?? text.length;
  const m = text.slice(0, caret).match(/@([^\s@[\]]*)$/);
  if (m) {
    setQuery(m[1]);
    setSel(0);
  } else {
    setQuery(null);
  }
}

function pick(it: Item) {
  const el = ref.current;
  if (!el) return;
  const text = el.value;
  const caret = el.selectionStart ?? text.length;
  const at = text.slice(0, caret).lastIndexOf("@");
  if (at < 0) return;
  onCite({ title: it.title, site: it.site, url: it.url });
  // Inline markdown link — rendered as a clickable title, editable as text.
  const token = `[${it.title}](${it.url}) `;
  const next = text.slice(0, at) + token + text.slice(caret);
  onChange(next);
  setQuery(null);
  requestAnimationFrame(() => {
    el.focus();
    const pos = at + token.length;
    el.setSelectionRange(pos, pos);
  });
}

