import { and, eq, lte, or } from "drizzle-orm";
import { getDb } from "@/db";
import { readLaterState } from "@/db/schema";
import type { InboxItem } from "@/lib/read-later/bucketing";

/**
 * The user's current "read later" queue: items still in the inbox, plus
 * snoozed items whose snooze has come due. Shared between the read-later
 * API route (which buckets these for the digest view) and the Ask
 * pipeline (which needs the same list to answer questions like "what's in
 * my read later list", since that's app state — not something present in
 * any saved page's own content).
 */
export async function getReadLaterQueue(userId: string): Promise<InboxItem[]> {
  const db = getDb();
  const now = new Date();

  const rows = await db.query.readLaterState.findMany({
    where: and(
      eq(readLaterState.userId, userId),
      or(
        eq(readLaterState.status, "inbox"),
        and(eq(readLaterState.status, "snoozed"), lte(readLaterState.snoozedUntil, now))
      )
    ),
    with: { savedUrl: true },
  });

  return rows
    .filter((row): row is typeof row & { savedUrl: NonNullable<typeof row.savedUrl> } =>
      Boolean(row.savedUrl)
    )
    .map((row) => ({ ...row.savedUrl, readLater: row }));
}

########## src/lib/search/keyword-search.ts ##########
import { and, arrayContains, desc, eq, gte, ilike, lte, or, type SQL, sql } from "drizzle-orm";
import { getDb } from "@/db";
import { savedUrls } from "@/db/schema";

export type SearchHit = typeof savedUrls.$inferSelect & { rank: number };

export interface ParsedQuery {
  /** Free-text portion, with any `domain:`/`tag:` tokens stripped out. */
  text: string;
  /** Value of a `domain:` token, lowercased and stripped of a leading `www.`. */
  domain: string | null;
  /** Values of every `tag:` token, lowercased. A hit must carry all of them. */
  tags: string[];
}

const FILTER_TOKEN = /(?:^|\s)(domain|tag):("[^"]+"|\S+)/gi;

/**
 * Pulls `domain:` and `tag:` filter tokens out of a raw search string so the
 * library search box doubles as a filter UI (issues #2, #5). Everything else
 * stays as free text for full-text search. `tag:"two words"` is supported.
 */
export function parseSearchQuery(raw: string): ParsedQuery {
  let domain: string | null = null;
  const tags: string[] = [];

  const text = raw
    .replace(FILTER_TOKEN, (_match, key: string, rawValue: string) => {
      const value = rawValue.replace(/^"|"$/g, "").trim().toLowerCase();
      if (value) {
        if (key.toLowerCase() === "domain") {
          domain = value.replace(/^www\./, "");
        } else {
          tags.push(value);
        }
      }
      return " ";
    })
    .replace(/\s+/g, " ")
    .trim();

  return { text, domain, tags };
}

export interface DateRange {
  /** Inclusive lower bound. */
  from?: Date;
  /** Inclusive upper bound. */
  to?: Date;
}

function dateRangeConditions({ from, to }: DateRange): SQL[] {
  const conditions: SQL[] = [];
  if (from) conditions.push(gte(savedUrls.createdAt, from));
  if (to) conditions.push(lte(savedUrls.createdAt, to));
  return conditions;
}

/**
 * Always-available search over a user's own saved URLs — no AI required.
 * Tries Postgres full-text search first (fast, ranked); if that comes back
 * empty (e.g. a short/odd query the tsquery parser doesn't like), falls
 * back to a plain ILIKE scan so search never just returns nothing.
 */
export async function searchUserItems(
  userId: string,
  query: string,
  { limit = 8, dateRange = {} }: { limit?: number; dateRange?: DateRange } = {}
): Promise<SearchHit[]> {
  const { text, domain, tags } = parseSearchQuery(query);
  const trimmed = text.trim();
  const hasFilters = domain !== null || tags.length > 0;
  if (!trimmed && !hasFilters) return [];

  const db = getDb();

  const scopeConditions: SQL[] = [eq(savedUrls.userId, userId), ...dateRangeConditions(dateRange)];
  if (domain) scopeConditions.push(ilike(savedUrls.domain, `%${domain}%`));
  if (tags.length > 0) scopeConditions.push(arrayContains(savedUrls.tags, tags));

  // Filters with no free text: just return the matching rows, newest first.
  if (!trimmed) {
    const rows = await db
      .select()
      .from(savedUrls)
      .where(and(...scopeConditions))
      .orderBy(desc(savedUrls.createdAt))
      .limit(limit);
    return rows.map((row) => ({ ...row, rank: 0 }));
  }

  const ftsRows = await db
    .select({
      row: savedUrls,
      rank: sql<number>`ts_rank(${savedUrls.searchVector}, plainto_tsquery('simple', ${trimmed}))`,
    })
    .from(savedUrls)
    .where(
      and(
        ...scopeConditions,
        sql`${savedUrls.searchVector} @@ plainto_tsquery('simple', ${trimmed})`
      )
    )
    .orderBy((t) => desc(t.rank))
    .limit(limit);

  if (ftsRows.length > 0) {
    return ftsRows.map(({ row, rank }) => ({ ...row, rank }));
  }

  const likeTerm = `%${trimmed}%`;
  const likeRows = await db
    .select()
    .from(savedUrls)
    .where(
      and(
        ...scopeConditions,
        or(
          ilike(savedUrls.title, likeTerm),
          ilike(savedUrls.description, likeTerm),
          ilike(savedUrls.summary, likeTerm),
          ilike(savedUrls.domain, likeTerm),
          ilike(savedUrls.extractedText, likeTerm)
        )
      )
    )
    .orderBy(desc(savedUrls.createdAt))
    .limit(limit);

  return likeRows.map((row) => ({ ...row, rank: 0 }));
}

/**
 * A user's most recently saved items, unfiltered by any query match.
 * Used as a last-resort fallback by callers (like Ask) that want to
 * ground answers in the user's library even when keyword search finds
 * no literal overlap with the question — e.g. natural-language questions
 * or a library whose content language differs from the question's.
 */
export async function getRecentUserItems(
  userId: string,
  limit: number,
  dateRange: DateRange = {}
): Promise<SearchHit[]> {
  const db = getDb();
  const rows = await db
    .select()
    .from(savedUrls)
    .where(and(eq(savedUrls.userId, userId), ...dateRangeConditions(dateRange)))
    .orderBy(desc(savedUrls.createdAt))
    .limit(limit);

  return rows.map((row) => ({ ...row, rank: 0 }));
}

########## src/lib/metadata/fetch-metadata.ts ##########
// `cheerio/slim` is the parse-only entry: it drops cheerio's URL-loading stack
// (undici, encoding-sniffer, whatwg-mimetype) which doesn't run on Workers and
// added ~1 MiB to the bundle. We only ever call `load()` on an already-fetched
// HTML string, so the slim build is a drop-in.
import * as cheerio from "cheerio/slim";

export type FetchedMetadata = {
  title: string | null;
  description: string | null;
  faviconUrl: string | null;
  ogImageUrl: string | null;
  contentLanguage: string | null;
  extractedText: string | null;
  estimatedReadMinutes: number | null;
};

export type FetchMetadataResult =
  | { status: "success"; metadata: FetchedMetadata }
  | { status: "error"; error: string };

const FETCH_TIMEOUT_MS = 8000;
const EXTRACTED_TEXT_CAP = 4000;
const WORDS_PER_MINUTE = 200;

function absoluteUrl(base: string, maybeRelative: string | undefined): string | null {
  if (!maybeRelative) return null;
  try {
    return new URL(maybeRelative, base).toString();
  } catch {
    return null;
  }
}

function detectLanguage(html: cheerio.CheerioAPI, text: string): string | null {
  const htmlLang = html("html").attr("lang");
  if (htmlLang) return htmlLang.split("-")[0].toLowerCase();
  // Cheap heuristic fallback: a meaningful share of CJK codepoints implies Japanese.
  const sample = text.slice(0, 400);
  const cjkMatches = sample.match(/[぀-ヿ㐀-䶿一-鿿]/g);
  if (cjkMatches && cjkMatches.length / Math.max(sample.length, 1) > 0.15) return "ja";
  return "en";
}

export async function fetchUrlMetadata(url: string): Promise<FetchMetadataResult> {
  try {
    const response = await fetch(url, {
      redirect: "follow",
      signal: AbortSignal.timeout(FETCH_TIMEOUT_MS),
      headers: {
        "User-Agent": "HazyBot/1.0 (+https://hazy.app; link preview fetcher)",
        Accept: "text/html,application/xhtml+xml",
      },
    });

    if (!response.ok) {
      return { status: "error", error: `Fetch failed with status ${response.status}` };
    }

    const contentType = response.headers.get("content-type") ?? "";
    if (!contentType.includes("text/html") && !contentType.includes("xhtml")) {
      return { status: "error", error: `Unsupported content type: ${contentType || "unknown"}` };
    }

    const html = await response.text();
    const $ = cheerio.load(html);
    const finalUrl = response.url || url;

    const ogTitle = $('meta[property="og:title"]').attr("content");
    const titleTag = $("title").first().text();
    const title = (ogTitle || titleTag || "").trim() || null;

    const ogDescription = $('meta[property="og:description"]').attr("content");
    const metaDescription = $('meta[name="description"]').attr("content");
    const description = (ogDescription || metaDescription || "").trim() || null;

    const ogImage = $('meta[property="og:image"]').attr("content");
    const ogImageUrl = absoluteUrl(finalUrl, ogImage);

    const iconHref =
      $('link[rel="icon"]').attr("href") ??
      $('link[rel="shortcut icon"]').attr("href") ??
      $('link[rel="apple-touch-icon"]').attr("href");
    const faviconUrl = absoluteUrl(finalUrl, iconHref) ?? absoluteUrl(finalUrl, "/favicon.ico");

    $("script, style, noscript, nav, footer").remove();
    const bodyText = $("body").text().replace(/\s+/g, " ").trim();
    const extractedText = bodyText ? bodyText.slice(0, EXTRACTED_TEXT_CAP) : null;

    const wordCount = bodyText ? bodyText.split(/\s+/).length : 0;
    const estimatedReadMinutes = wordCount
      ? Math.max(1, Math.round(wordCount / WORDS_PER_MINUTE))
      : null;

    const contentLanguage = detectLanguage($, bodyText);

    return {
      status: "success",
      metadata: {
        title,
        description,
        faviconUrl,
        ogImageUrl,
        contentLanguage,
        extractedText,
        estimatedReadMinutes,
      },
    };
  } catch (error) {
    const message =
      error instanceof Error
        ? error.name === "TimeoutError" || error.name === "AbortError"
          ? "Timed out fetching the page."
          : error.message
        : "Unknown fetch error";
    return { status: "error", error: message };
  }
}

