360	/**
361	 * Collects up to {@link PREVIEW_IMAGES_PER_COLLECTION} recent og:image URLs
362	 * for each collection so the collections grid can render a preview thumbnail
363	 * built from the images of the links saved inside it.
364	 */
365	async function buildPreviewMap(
366	  db: ReturnType<typeof getDb>,
367	  collectionIds: string[]
368	): Promise<Map<string, string[]>> {
369	  const map = new Map<string, string[]>();
370	  if (collectionIds.length === 0) return map;
371	
372	  const imageRows = await db
373	    .select({
374	      collectionId: collectionItems.collectionId,
375	      ogImageUrl: savedUrls.ogImageUrl,
376	    })
377	    .from(collectionItems)
378	    .innerJoin(savedUrls, eq(savedUrls.id, collectionItems.savedUrlId))
379	    .where(
380	      and(inArray(collectionItems.collectionId, collectionIds), isNotNull(savedUrls.ogImageUrl))
381	    )
382	    .orderBy(desc(collectionItems.createdAt));
383	
384	  for (const { collectionId, ogImageUrl } of imageRows) {
385	    if (!ogImageUrl) continue;
386	    const existing = map.get(collectionId) ?? [];
387	    if (existing.length >= PREVIEW_IMAGES_PER_COLLECTION || existing.includes(ogImageUrl)) continue;
388	    existing.push(ogImageUrl);
389	    map.set(collectionId, existing);
390	  }
391	
392	  return map;
393	}
