649	const listQuerySchema = z.object({
650	  cursor: z.string().uuid().optional(),
651	  limit: z.coerce.number().int().min(1).max(100).default(30),
652	  sort: z.enum(["newest", "oldest"]).default("newest"),
653	});
654	
655	export const GET = withApiErrors(async (req: Request) => {
656	  const user = await requireUser();
657	  const { searchParams } = new URL(req.url);
658	  const { cursor, limit, sort } = listQuerySchema.parse({
659	    cursor: searchParams.get("cursor") ?? undefined,
660	    limit: searchParams.get("limit") ?? undefined,
661	    sort: searchParams.get("sort") ?? undefined,
662	  });
663	  const db = getDb();
664	
665	  let cursorCreatedAt: Date | undefined;
666	  if (cursor) {
667	    const cursorRow = await db.query.savedUrls.findFirst({ where: eq(savedUrls.id, cursor) });
668	    cursorCreatedAt = cursorRow?.createdAt;
669	  }
670	
671	  const conditions = [eq(savedUrls.userId, user.id)];
672	  if (cursorCreatedAt) {
673	    conditions.push(
674	      sort === "newest"
675	        ? lt(savedUrls.createdAt, cursorCreatedAt)
676	        : gt(savedUrls.createdAt, cursorCreatedAt)
677	    );
678	  }
679	
680	  const rows = await db.query.savedUrls.findMany({
681	    where: and(...conditions),
682	    orderBy: sort === "newest" ? [desc(savedUrls.createdAt)] : [asc(savedUrls.createdAt)],
683	    limit: limit + 1,
684	    with: { readLaterState: true },
685	  });
686	
687	  const hasMore = rows.length > limit;
688	  const page = hasMore ? rows.slice(0, limit) : rows;
689	
690	  return ok({
691	    items: page.map((row) => serializeSavedUrl(row, row.readLaterState)),
692	    nextCursor: hasMore ? page[page.length - 1].id : null,
693	  });
694	});
