835	
836	export const runtime = "nodejs";
837	
838	const DAY_MS = 24 * 60 * 60 * 1000;
839	
840	export const GET = withApiErrors(async () => {
841	  const user = await requireUser();
842	  const db = getDb();
843	
844	  const weekAgo = new Date(Date.now() - 7 * DAY_MS);
845	
846	  const [readRows, savedRows] = await Promise.all([
847	    db.query.readLaterState.findMany({
848	      where: and(
849	        eq(readLaterState.userId, user.id),
850	        eq(readLaterState.status, "read"),
851	        gte(readLaterState.markedReadAt, weekAgo)
852	      ),
853	    }),
854	    db.query.savedUrls.findMany({
855	      where: and(eq(savedUrls.userId, user.id), gte(savedUrls.createdAt, weekAgo)),
856	    }),
857	  ]);
858	
859	  // 7 buckets, oldest -> newest, counting items read that day.
860	  const days = Array.from({ length: 7 }, (_, i) => {
861	    const dayStart = new Date(Date.now() - (6 - i) * DAY_MS);
862	    dayStart.setHours(0, 0, 0, 0);
863	    const dayEnd = new Date(dayStart.getTime() + DAY_MS);
864	    const count = readRows.filter(
865	      (r) => r.markedReadAt && r.markedReadAt >= dayStart && r.markedReadAt < dayEnd
866	    ).length;
867	    return count;
868	  });
869	
870	  const maxDay = Math.max(1, ...days);
871	
872	  return ok({
873	    days: days.map((count) => ({ count, heightPct: Math.round((count / maxDay) * 100) })),
874	    readThisWeek: readRows.length,
875	    savedThisWeek: savedRows.length,
876	  });
877	});
