/**
 * The wire contract for the hazy API (`https://api.hz.nknighta.me`, served at
 * `/v1/**`). This module is the single source of truth every Route Handler in
 * `apps/api` returns data matching, and every client — the hazy web app today,
 * a Flutter app later — is built against.
 *
 * Success responses are wrapped in `{ data: T }`, failures in
 * `{ error: { code, message, details? } }` (see `apps/api/src/lib/api/response.ts`).
 */

export type SavedUrlDTO = {
  id: string;
  url: string;
  domain: string | null;
  title: string | null;
  description: string | null;
  faviconUrl: string | null;
  ogImageUrl: string | null;
  summary: string | null;
  tags: string[];
  contentLanguage: string | null;
  estimatedReadMinutes: number | null;
  fetchStatus: "pending" | "success" | "error";
  fetchError: string | null;
  createdAt: string;
  updatedAt: string;
  readLaterStatus: "inbox" | "snoozed" | "read" | "archived" | null;
};

export type PaginatedResponse<T> = {
  items: T[];
  nextCursor: string | null;
};

export type CollectionDTO = {
  id: string;
  name: string;
  description: string | null;
  color: string | null;
  /** AI-generated overview of the whole collection; null until generated. */
  summary: string | null;
  summaryUpdatedAt: string | null;
  itemCount: number;
  /** Up to 4 recent og:image URLs from the collection's items, for a preview thumbnail. */
  previewImages: string[];
  createdAt: string;
};

/** GET /v1/collections/:id — a collection plus its saved URLs. */
export type CollectionDetailDTO = CollectionDTO & { items: SavedUrlDTO[] };

/** POST /v1/collections/:id/summarize */
export type CollectionSummaryDTO = { summary: string; summaryUpdatedAt: string };

/** POST /v1/collections/:id/items, DELETE /v1/collections/:id/items/:savedUrlId */
export type CollectionItemRefDTO = { collectionId: string; savedUrlId: string };

export type AskCitationDTO = {
  savedUrlId: string;
  title: string | null;
  domain: string | null;
  url: string;
  faviconUrl: string | null;
  snippet: string;
  rank: number;
};

export type AskMessageDTO = {
  id: string;
  role: "user" | "assistant";
  content: string;
  modelId: string | null;
  usedFallback: boolean;
  createdAt: string;
  citations?: AskCitationDTO[];
};

export type AskThreadDTO = {
  id: string;
  title: string;
  createdAt: string;
  updatedAt: string;
};

export type AskThreadListDTO = { items: AskThreadDTO[] };

/** GET /v1/ask/threads/:id */
export type AskThreadDetailDTO = { thread: AskThreadDTO; messages: AskMessageDTO[] };

export type AskResponseDTO = {
  thread: AskThreadDTO;
  message: AskMessageDTO;
  citations: AskCitationDTO[];
  meta: { sourceCount: number };
};

export type UserPreferencesDTO = {
  interfaceLocale: "en" | "ja";
  answerLanguageMode: "interface" | "source";
  notifyReadLaterDigest: boolean;
  notifyWeeklyStats: boolean;
};

/** GET /v1/me */
export type MeDTO = {
  id: string;
  email: string | null;
  displayName: string | null;
  avatarUrl: string | null;
  preferences: UserPreferencesDTO;
};

/** GET /v1/read-later */
export type ReadLaterQueueDTO = {
  totalCount: number;
  totalMinutes: number;
  todaysThreeMinutes: number;
  todaysThree: SavedUrlDTO[];
  fiveMinutes: SavedUrlDTO[];
  sitDown: SavedUrlDTO[];
};

/** GET /v1/read-later/stats */
export type ReadLaterStatsDTO = {
  days: { count: number; heightPct: number }[];
  readThisWeek: number;
  savedThisWeek: number;
};

/** PATCH /v1/read-later/:itemId — the updated read-later state row. */
export type ReadLaterStateDTO = {
  status: "inbox" | "snoozed" | "read" | "archived";
  snoozedUntil: string | null;
  markedReadAt: string | null;
};

/** GET /v1/search */
export type SearchResponseDTO = { query: string; items: SavedUrlDTO[] };

export type ReadLaterStatus = "inbox" | "snoozed" | "read" | "archived";

import type {
  AskResponseDTO,
  AskThreadDetailDTO,
  AskThreadListDTO,
  CollectionDTO,
  CollectionDetailDTO,
  CollectionItemRefDTO,
  CollectionSummaryDTO,
  MeDTO,
  PaginatedResponse,
  ReadLaterQueueDTO,
  ReadLaterStateDTO,
  ReadLaterStatsDTO,
  ReadLaterStatus,
  SavedUrlDTO,
  SearchResponseDTO,
} from "./types";

/** Thrown for every non-2xx response and every `{ error }` envelope. */
export class ApiClientError extends Error {
  constructor(
    readonly code: string,
    message: string,
    readonly status: number,
    readonly details?: unknown
  ) {
    super(message);
    this.name = "ApiClientError";
  }
}

export interface HazyClientConfig {
  /** e.g. `https://api.hz.nknighta.me` (no trailing `/v1`). */
  baseUrl: string;
  /** Resolves the current Clerk session token, or null when signed out. */
  getToken: () => Promise<string | null>;
}

type RequestInitLite = {
  method?: string;
  body?: unknown;
  query?: Record<string, string | number | boolean | undefined>;
  signal?: AbortSignal;
};

type Envelope<T> =
  | { data: T }
  | { error: { code: string; message: string; details?: unknown } };

function createRequest(config: HazyClientConfig) {
  return async function request<T>(path: string, init: RequestInitLite = {}): Promise<T> {
    const url = new URL(`/v1${path}`, config.baseUrl);
    for (const [key, value] of Object.entries(init.query ?? {})) {
      if (value !== undefined) url.searchParams.set(key, String(value));
    }

    const token = await config.getToken();
    const res = await fetch(url, {
      method: init.method ?? "GET",
      headers: {
        ...(init.body !== undefined ? { "Content-Type": "application/json" } : {}),
        ...(token ? { Authorization: `Bearer ${token}` } : {}),
      },
      body: init.body !== undefined ? JSON.stringify(init.body) : undefined,
      signal: init.signal,
    });

    const json = (await res.json().catch(() => null)) as Envelope<T> | null;
    if (json && "error" in json) {
      throw new ApiClientError(json.error.code, json.error.message, res.status, json.error.details);
    }
    if (!res.ok || !json || !("data" in json)) {
      throw new ApiClientError("internal_error", `Request failed (${res.status})`, res.status);
    }
    return json.data;
  };
}

export interface ItemPatch {
  title?: string | null;
  summary?: string | null;
  tags?: string[];
}

export interface CollectionPatch {
  name?: string;
  description?: string | null;
  color?: string | null;
}

export interface AskInput {
  question: string;
  answerLanguageOverride?: "en" | "ja";
  collectionIds?: string[];
}

export function createHazyClient(config: HazyClientConfig) {
  const request = createRequest(config);

  return {
    items: {
      list: (
        query: { sort?: "newest" | "oldest"; cursor?: string; limit?: number } = {},
        signal?: AbortSignal
      ) => request<PaginatedResponse<SavedUrlDTO>>("/items", { query, signal }),
      save: (url: string) => request<SavedUrlDTO>("/items", { method: "POST", body: { url } }),
      get: (id: string, signal?: AbortSignal) =>
        request<SavedUrlDTO>(`/items/${id}`, { signal }),
      update: (id: string, patch: ItemPatch) =>
        request<SavedUrlDTO>(`/items/${id}`, { method: "PATCH", body: patch }),
      remove: (id: string) => request<{ id: string }>(`/items/${id}`, { method: "DELETE" }),
      refetch: (id: string) =>
        request<SavedUrlDTO>(`/items/${id}/refetch`, { method: "POST" }),
      summarize: (id: string) =>
        request<SavedUrlDTO>(`/items/${id}/summarize`, { method: "POST" }),
    },

    collections: {
      list: () => request<{ items: CollectionDTO[] }>("/collections"),
      get: (id: string, signal?: AbortSignal) =>
        request<CollectionDetailDTO>(`/collections/${id}`, { signal }),
      create: (input: { name: string; description?: string; color?: string }) =>
        request<CollectionDTO>("/collections", { method: "POST", body: input }),
      update: (id: string, patch: CollectionPatch) =>
        request<CollectionDTO>(`/collections/${id}`, { method: "PATCH", body: patch }),
      remove: (id: string) =>
        request<{ id: string }>(`/collections/${id}`, { method: "DELETE" }),
      addItem: (collectionId: string, savedUrlId: string) =>
        request<CollectionItemRefDTO>(`/collections/${collectionId}/items`, {
          method: "POST",
          body: { savedUrlId },
        }),
      removeItem: (collectionId: string, savedUrlId: string) =>
        request<CollectionItemRefDTO>(`/collections/${collectionId}/items/${savedUrlId}`, {
          method: "DELETE",
        }),
      summarize: (id: string, locale?: "en" | "ja") =>
        request<CollectionSummaryDTO>(`/collections/${id}/summarize`, {
          method: "POST",
          body: { locale },
        }),
    },

    ask: {
      ask: (input: AskInput) => request<AskResponseDTO>("/ask", { method: "POST", body: input }),
      threads: () => request<AskThreadListDTO>("/ask/threads"),
      thread: (id: string, signal?: AbortSignal) =>
        request<AskThreadDetailDTO>(`/ask/threads/${id}`, { signal }),
      deleteThread: (id: string) =>
        request<{ id: string }>(`/ask/threads/${id}`, { method: "DELETE" }),
      followUp: (threadId: string, input: AskInput) =>
        request<AskResponseDTO>(`/ask/threads/${threadId}/messages`, {
          method: "POST",
          body: input,
        }),
    },

    readLater: {
      queue: () => request<ReadLaterQueueDTO>("/read-later"),
      stats: () => request<ReadLaterStatsDTO>("/read-later/stats"),
      setStatus: (input: {
        itemId: string;
        status: ReadLaterStatus;
        snoozedUntil?: string;
      }) =>
        request<ReadLaterStateDTO>(`/read-later/${input.itemId}`, {
          method: "PATCH",
          body: { status: input.status, snoozedUntil: input.snoozedUntil },
        }),
    },

    search: (q: string, limit?: number, signal?: AbortSignal) =>
      request<SearchResponseDTO>("/search", { query: { q, limit }, signal }),

    me: {
      get: () => request<MeDTO>("/me"),
      updatePreferences: (patch: Partial<MeDTO["preferences"]>) =>
        request<MeDTO["preferences"]>("/me", { method: "PATCH", body: patch }),
    },
  };
}

export type HazyClient = ReturnType<typeof createHazyClient>;

