      type: "suggestion";
      kind: string; // "抜けている反論 — 段落の下書き"
      text: string;
      ref?: string;
    };

export interface NoteSourceRef {
  n: number;
  label: string;
  cited: boolean;
  url?: string;
}

export interface NoteLink {
  noteId: string;
  title: string;
  reason: string;
}

export interface Note {
  id: string;
  title: string;
  projectId: string;
  tags: { label: string; tone: "accent" | "neutral" | "outline" }[];
  status: NoteStatus;
  updatedLabel: string;
  blocks: NoteBlock[];
  sources: NoteSourceRef[];
  links: NoteLink[];
  flags: { icon: string; tone: string; text: string }[];
}

export interface CompareAxis {
  name: string;
  values: (string | null)[];
  accentCols: number[]; // column indices rendered in accent (the disagreements)
}

export interface CompareBoard {
  id: string;
  projectId: string;
  sources: string[];
  axes: CompareAxis[];
  summary: string;
  candidateAxes: string[];
}

export interface GraphNode {
  id: string;
  label: string;
  kind: "note" | "tag" | "source";
  x: number;
  y: number;
  r: number;
  focus?: boolean;
  unreadLabel?: string;
}

export interface GraphEdge {
  id: string;
  from: string;
  to: string;
  kind: "citation" | "hypothesis";
  reason?: string;
  title?: string;
}

export interface GraphData {
  nodes: GraphNode[];
  edges: GraphEdge[];
  isolated: string[];
}

export interface Digest {
  unsorted: number;
  message: string;
}

export type ExportFormat = "blog" | "memo" | "bullets";

export interface ExportSectionProvenance {
  heading: string;
  from: string;
  tone: "accent" | "muted";
}

export interface ExportDraft {
  format: ExportFormat;
  meta: string; // "約1,800字 · 読了6分"
  title: string;
  blocks: (
    | { type: "p"; text: string; dim?: boolean }
    | { type: "h4"; text: string }
    | { type: "note"; tone: string; text: string }
  )[];
  provenance: ExportSectionProvenance[];
  warning?: string;
}

