26	/** `id` is undefined for the `/notes/new` draft — nothing is written to the
27	 *  DB until the first real edit. */
28	export function NoteClient({ id }: { id?: string }) {
29	  const router = useRouter();
30	  const [noteId, setNoteId] = useState<string | undefined>(id);
31	  const [note, setNote] = useState<Note | null>(id ? null : BLANK);
32	  const [showInline, setShowInline] = useState(true);
33	  const [draft, setDraft] = useState("");
34	  const [notFound, setNotFound] = useState(false);
35	  const [saving, setSaving] = useState(false);
36	  const isDraft = !noteId;
37	
38	  // The authoritative note / id, updated synchronously so rapid edits chain
39	  // correctly instead of building off a stale render.
40	  const noteRef = useRef<Note | null>(note);
41	  const idRef = useRef<string | undefined>(noteId);
42	  const chain = useRef<Promise<unknown>>(Promise.resolve());
43	  const adopt = (n: Note) => {
44	    noteRef.current = n;
45	    setNote(n);
46	  };
47	
48	  const load = useCallback(() => {
49	    if (!noteId) return;
50	    api.note(noteId).then(adopt).catch(() => setNotFound(true));
51	  }, [noteId]);
52	  useEffect(() => {
53	    load();
54	  }, [load]);
55	
56	  /** Append a write to the queue — never runs two at once, and a failure
57	   * doesn't stall the queue. */
58	  function enqueue(job: () => Promise<void>) {
59	    chain.current = chain.current
60	      .then(async () => {
61	        setSaving(true);
62	        try {
63	          await job();
64	        } finally {
65	          setSaving(false);
66	        }
67	      })
68	      .catch((e) => {
69	        console.error("note write failed", e);
70	        setSaving(false);
71	      });
72	  }
73	
74	  /**
75	   * Apply an edit. The local state changes immediately; the write is queued so
76	   * overlapping edits never race (each write replaces the whole note). On a
77	   * `/notes/new` draft the first edit is what creates the row — after that it's
78	   * a PATCH and the URL is swapped in place (no navigation, no lost focus).
79	   */
80	  function mutate(patch: Partial<Note>) {
81	    const base = noteRef.current;
82	    if (!base) return;
83	    const next = { ...base, ...patch };
84	    adopt(next);
85	    enqueue(async () => {
86	      const cur = noteRef.current;
87	      if (!cur) return;
88	      const payload = {
89	        title: cur.title,
90	        blocks: cur.blocks,
91	        tags: cur.tags,
92	        status: cur.status,
93	        sources: cur.sources,
94	      };
95	      if (idRef.current) {
96	        const saved = await api.updateNote(idRef.current, payload);
97	        noteRef.current = { ...noteRef.current!, updatedLabel: saved.updatedLabel };
98	        setNote(noteRef.current);
99	      } else {
100	        const created = await api.addNote(payload);
101	        idRef.current = created.id;
102	        setNoteId(created.id);
103	        window.history.replaceState(null, "", `/notes/${created.id}`);
104	        noteRef.current = { ...noteRef.current!, id: created.id, updatedLabel: created.updatedLabel };
105	        setNote(noteRef.current);
106	      }
107	    });
108	  }
109	
110	  function act(i: number, action: "accept" | "dismiss") {
111	    if (!idRef.current) return; // suggestions only exist on saved notes
112	    enqueue(async () => {
113	      adopt(await api.suggestion(idRef.current as string, i, action));
114	    });
115	  }
116	
117	  /** Record an `@`-cited URL as a source of this note. */
118	  function cite(t: CiteTarget) {
119	    const base = noteRef.current;
120	    if (!base) return;
121	    const label = `${t.title} — ${t.site}`;
122	    if (base.sources.some((s) => s.url === t.url || s.label === label)) return;
123	    const n = base.sources.reduce((m, s) => Math.max(m, s.n), 0) + 1;
124	    mutate({ sources: [...base.sources, { n, label, cited: true, url: t.url }] });
125	  }
126	
127	  function editBlockText(i: number, text: string) {
128	    const b = noteRef.current;
129	    if (!b) return;
130	    const current = b.blocks[i];
131	    if (!current || !("text" in current) || current.text === text) return;
132	    if (!text.trim()) return deleteBlock(i);
133	    mutate({ blocks: b.blocks.map((x, j) => (j === i ? { ...x, text } : x)) });
134	  }
