  userId: string,
  noteId: string,
  format: ExportFormat = "blog"
): Promise<ExportDraft> {
  let note = await getNote(userId, noteId);
  if (!note) {
    const fallback = await db.query.notes.findFirst({
      where: (t, { eq }) => eq(t.userId, userId),
