    const ids = new Set(nodes.map((n) => n.id));
    return (Array.isArray(out.edges) ? out.edges : [])
      .filter((e) => e && ids.has(e.from) && ids.has(e.to) && e.from !== e.to)
      .slice(0, 5);
  } catch (e) {
    if (!(e instanceof LLMError)) throw e;
    return [];
  }
}

